"""Engineering forecasts from seven process blocks, without inferential claims."""
from pathlib import Path
import json,hashlib,statistics
R=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 source=R/'runtime/interface-timing-131/timing.json';z=json.loads(source.read_text(encoding='utf-8'));assert z['fresh_process_blocks']==7 and z['warm_repetitions_per_task_per_block']==5;blocks=[json.loads((source.parent/('block-'+str(i)+'.json')).read_text(encoding='utf-8')) for i in range(7)];assert len({b['process_id'] for b in blocks})==7
 for path,h in z['bindings'].items():assert sha(R/path)==h,'timing snapshot changed'
 for b in blocks:
  assert len(b['schedule'])==len(set(b['schedule']))==25 and len(b['tasks'])==25
  for row in b['tasks']:assert len(row['samples_ns'])==5 and row['within_block_median_ns']==statistics.median(row['samples_ns']) and row['result_checked_each_time']
 rows={r['task']:r for r in z['aggregate']};forecasts=[]
 for name,row in rows.items():
  med=[next(t for t in b['tasks'] if t['task']==name)['within_block_median_ns'] for b in blocks];assert med==row['block_medians_ns'] and statistics.median(med)==row['median_ns'];forecasts.append({'task':name,'median_ms':row['median_ns']/10**6,'block_median_range_ms':[min(med)/10**6,max(med)/10**6],'fixed_workload_1000_serial_hot_calls_seconds':row['median_ns']/10**6,'scope':'linear repetition of this same bound input; adapter includes its own checks; no new-scale or search-time claim','input_sha256':row['input_sha256'],'maximum_rational_component_bits':row['maximum_rational_component_bits']})
 # Predeclared 64-target holdout is not used to set this bracket. The same
 # dense geometry has k^2 pair work and at most cubic DFS matching work.
 train=[rows['hall_scale_'+str(k)] for k in (4,8,16,32)];anchor=train[-1];hold=rows['hall_scale_64'];ratio=64/32;bit_ratio=max(1,hold['maximum_rational_component_bits']/anchor['maximum_rational_component_bits']);lower=anchor['minimum_block_median_ns']*ratio**2;upper=anchor['maximum_block_median_ns']*ratio**3*bit_ratio**2;prediction={'training_target_sizes':[4,8,16,32],'held_out_targets':64,'model':'anchor at32; k^2 geometry to k^3 dense augmenting-path work; conservative squared-bit-ratio penalty only in upper engineering forecast','lower_predicted_ms':lower/10**6,'upper_predicted_ms':upper/10**6,'heldout_actual_median_ms':hold['median_ns']/10**6,'actual_inside_engineering_bracket':lower<=hold['median_ns']<=upper,'actual_over_quadratic_anchor':hold['median_ns']/(anchor['median_ns']*ratio**2),'scope':'empirical engineering bracket on controlled dense equal-size boxes; not a mathematical wall-time bound or general Hall-discovery success rate'}
 out=R/'verify/out/n100-interface-timing-calibration.json';assert not out.exists();paths=[source]+[source.parent/('block-'+str(i)+'.json') for i in range(7)];out.write_text(json.dumps({'schema':'n100-interface-timing-calibration/v1','seven_distinct_processes_verified':True,'total_checked_hot_samples':7*25*5,'hot_forecasts':forecasts,'cold_context_setups':z['setups'],'hall_holdout_prediction':prediction,'environment':z['environment'],'process_elapsed_ns':z['process_elapsed_ns'],'limitations':['only Hall has a multi-scale calibration in this batch','OS file cache not cleared; setup order fixed and recorded; hot task order randomized per block','discovery of SOS/maps/global trees not timed','five warm calls in a block are not independent process replicates','timing telemetry never supplies a geometric verdict'],'mathematical_verdict':None,'bindings':{p.relative_to(R).as_posix():sha(p) for p in paths},'script_sha256':sha(Path(__file__))},indent=2)+'\n',encoding='utf-8');print('PASS timing calibration;875 checked hot samples;7 distinct processes;holdout',prediction['actual_inside_engineering_bracket']);print('HOLDOUT',json.dumps(prediction));print('SETUPS',json.dumps([(s['name'],round(s['median_ns']/10**6,3)) for s in z['setups']]));print('HOT',json.dumps([(r['task'],round(r['median_ms'],4)) for r in forecasts]))
if __name__=='__main__':main()
